<?php
declare(strict_types=1);namespace HardnessMcp\Tools\Catalog;require_once dirname(__DIR__).'/LegacyReports/LegacyReportsTools.php';use HardnessMcp\Tenant\ResolvedTenantContext;use HardnessMcp\Tools\LegacyReports\{LegacyReportCatalog,LegacyReportDownloadLinkService,LegacyReportGateway,LegacyReportsGetTool,LegacyReportsListTool};use HardnessMcp\Tools\ToolInterface;use PDO;
final class LegacyReportsToolsModule implements ToolModuleInterface {private LegacyReportCatalog $catalog;private LegacyReportGateway $gateway;private ?LegacyReportDownloadLinkService $downloads;private string $directory;private string $database;public function __construct(LegacyReportCatalog $catalog,LegacyReportGateway $gateway,?LegacyReportDownloadLinkService $downloads=null,string $directory='',string $database=''){$this->catalog=$catalog;$this->gateway=$gateway;$this->downloads=$downloads;$this->directory=$directory;$this->database=$database;}public static function fromRuntime(PDO $pdo,ResolvedTenantContext $tenant,string $erpRootPath,string $downloadSecret):self{$database=$tenant->getDatabase();return new self(LegacyReportCatalog::fromTenant($erpRootPath,$database),new LegacyReportGateway($pdo,$tenant),new LegacyReportDownloadLinkService($tenant->getRootUrl(),$downloadSecret),rtrim($erpRootPath,'/').'/dados_usuarios/'.$database.'/mcp/legacy-reports',$database);}public static function unavailable(PDO $pdo):self{return new self(new LegacyReportCatalog(),new LegacyReportGateway($pdo,null));}/** @return ToolInterface[] */public function tools():array{return [new LegacyReportsListTool($this->catalog),new LegacyReportsGetTool($this->catalog,$this->gateway,$this->downloads,$this->directory,$this->database)];}}
